function this.GetRawImage(path, cacheTime)
    if not this.spriteLoader then
        this.spriteLoader = CS.TCFramework.AssetLoader(nil)
    end
    this.spriteLoader:LoadRawImage(path, cacheTime or CS.ResourceLoadMgr.ASSET_CACHE_TIME_USE_DEFAULT)
    if this.spriteLoader.request then
        return this.spriteLoader.request.asset
    end
end

---@alias LoadSpriteCallback fun(self: table, sprite: UnityEngine.Sprite,data:any):void
---@param callback LoadSpriteCallback
---@return void @非UI逻辑加载Res文件夹中的Sprite 同步加载
function this.LoadSprite(self, path, callback, data, cacheTime)
    this.GetSpriteLoader():Load(path, typeof(CS.UnityEngine.Sprite), cacheTime or CS.ResourceLoadMgr.ASSET_CACHE_TIME_USE_DEFAULT)
    if this.spriteLoader.request then
        callback(self, this.spriteLoader.request.asset, data)
    end
end
---@param callback LoadSpriteCallback
---@return void @非UI逻辑加载Res文件夹中的Sprite 同步加载
function this.LoadSpriteAsync(self, path, callback, data, cacheTime)
    this.GetSpriteLoader():LoadAsync(path, typeof(CS.UnityEngine.Sprite), cacheTime or CS.ResourceLoadMgr.ASSET_CACHE_TIME_USE_DEFAULT)
    if this.spriteLoader.isLoading then
        this.spriteLoader.loadCallback = function(sprite)
            callback(self, sprite, data,this.spriteLoader.request)
        end
    else
        callback(self, this.spriteLoader.request.asset, data,this.spriteLoader.request)
    end
end

