---@return void @临时，后续需要整理
---@param assetGroup TCFramework.AssetGroup
function this.SetSpriteFromAtlas(assetGroup, atlasName, iconName, arg)
    local atlasPath = string.format("Atlas/%s.spriteatlas", atlasName)
    local spriteAtlas = assetGroup:LoadAsset(atlasPath, typeof(CS.UnityEngine.U2D.SpriteAtlas))
    if not spriteAtlas then
        return
    end
    local sprite = spriteAtlas:GetSprite(tostring(iconName))
    if (sprite ~= nil and iconName ~= nil) then
        sprite.name = tostring(iconName)
        local typeArg = type(arg)
        if typeArg == "function" then
            ---@type function
            local callBack = arg
            callBack(sprite)
        elseif typeArg == "table" then
            if IsSubTypeOf(arg, UIControl) then
                ---@type UIControl
                local ui = arg
                ui:SetSprite(sprite)
            end
        end
        return sprite
    else
        logError(atlasName .. " 图集中没有发现 imageTable.IconName " .. iconName)
    end
end

---@param coord1 Dot2
---@param coord2 Dot2
---@return EDirection
function this.GetDirectionByTarget(coord1, coord2)
    if coord1 == coord2 then
        return EDirection.None
    end
    this.tempDot:CopyFromSub(coord2, coord1)
    this.tempDot:SetNormalize()
    local max = -math.huge
    local dir = EDirection.None
    if DebugFlag.isOpti_DisableModel then
        for k, v in pairs(EDirectionToDot2_Normalize) do
            local dot = Dot2.Dot(v, this.tempDot)
            if dot > max then
                max = dot
                dir = k
            end
        end
    else
        for k, v in pairs(EDirectionToDot2) do
            this.tempDot2:Copy(v)
            local dot = Dot2.Dot(this.tempDot2:SetNormalize(), this.tempDot)
            if dot > max then
                max = dot
                dir = k
            end
        end 
    end
    return dir
end

---@return number @8方向或者16方向，16方向从0开始到15.顺时针依次增加
function this.GetEffectDirection(coord1, coord2, is16Dir)
    if not is16Dir then
        return this.GetDirectionByTarget(coord1, coord2)
    end
    if coord1 == coord2 then
        return EDirection.None
    end
    local stepAngle = is16Dir and 22.5 or 45
    local up = Dot2(0, -1)
    local dot = coord2 - coord1
    local upVec = Vector3(up.x, up.z, 0)
    local dotVec = Vector3(dot.x, dot.z, 0)
    local cross = Vector3.Cross(upVec, dotVec)
    local angle = Vector3.Angle(upVec, dotVec)
    if cross.z > 0 then
        angle = angle
    else
        angle = 360 - angle
    end

    local index = Mathf.Round(angle / stepAngle)
    return index
end

