function Misc.IsOnUI()
    if CS.TCFramework.DebugTool.hasInstance and not CS.TCFramework.DebugTool.instance.minimize then
        return true
    end
    if EventSystem.current == null then
        return false
    end
    if Main.isEditor then
        return EventSystem.current:IsPointerOverGameObject()
    end
    if Main.isAndroid or Main.isIOS or Main.isWebGL then
        if Main.isWebGLBrowser then
            local isPointerOverGameObject = EventSystem.current:IsPointerOverGameObject()
            if not isPointerOverGameObject then
                if Input.touchCount > 0 then
                    return EventSystem.current:IsPointerOverGameObject(Input.GetTouch(0).fingerId)
                end
            end
            return isPointerOverGameObject
        end
        if Input.touchCount > 0 then
            return EventSystem.current:IsPointerOverGameObject(Input.GetTouch(0).fingerId)
        end
        return false
    else
        return EventSystem.current:IsPointerOverGameObject()
    end
end

---@return boolean @不要在Update中一直调用
function this.IsFocusOnInputText()
    if ObjectEx.IsNull(EventSystem.current.currentSelectedGameObject) then
        this.isSelectInputField = false
        this.currentUISelectedGameObject = nil
        return this.isSelectInputField
    end

    if this.currentUISelectedGameObject == EventSystem.current.currentSelectedGameObject then
        return this.isSelectInputField
    end
    this.currentUISelectedGameObject = EventSystem.current.currentSelectedGameObject
    logError(EventSystem.current.currentSelectedGameObject.name)
    this.isSelectInputField = ObjectEx.IsNull(this.currentUISelectedGameObject.transform:GetComponent(typeof(CS.UnityEngine.UI.InputField))) == false
    return this.isSelectInputField
end

