---@param trans UnityEngine.Transform
function this.SetSceneGoTrans(trans, pos, rotaion, scale)
    if not pos then
        pos = Vector3.zeroNonAlloc
    end
    if not rotaion then
        rotaion =cfg_global_post.cameraAndTerrainDatas and cfg_global_post.cameraAndTerrainDatas.rotation or  EngineMgr.sceneGoRotaion
    end
    if not scale then
        scale = EngineMgr.modelScale
    end
    this.tempRotation:EulerNonAlloc(rotaion.x, rotaion.y, rotaion.z)
    local q = this.tempRotation
    trans:SetLocalPosAndLocalRotAndLocalScale(pos.x, pos.y, pos.z, q.x, q.y, q.z, q.w, scale.x, scale.y, scale.z)
end

---@param trans UnityEngine.Transform
function this.SetSceneEffectGoTrans(trans, pos)
    if EngineMgr.isEffect2D then
        if EngineMgr.engineType == EEngineType.Base then
            this.SetSceneGoTrans(trans, pos, RoleHeadCfg.headRotation, this.scaleOne)
        elseif EngineMgr.engineType == EEngineType.QJ then
            this.SetSceneGoTrans(trans, pos, RoleHeadCfg.headRotation, this.scaleOne)
            local f = -trans.forward * 50 + pos
            trans:SetLocalPosition(f.x, f.y, f.z)
        end
    else
        this.SetSceneGoTrans(trans, pos)
    end
end

