--- 转化标签文本
--- like <Text|x=25|y=20|color=250|size=18|text=施毒术使用必需品.>|<Text|x=25|y=20|color=251|size=18|text=施毒术造成红毒效果.>
function this.TransSpecialText(srcString)
    if not string.contains(srcString, "<Text") then
        return srcString
    end
    local strList = string.split(srcString, '>')
    local retStrList = {}
    local retStr = ""
    --like {<Text|x=25|y=20|color=250|size=18|text=施毒术使用必需品., |<Text|x=25|y=20|color=251|size=18|text=施毒术造成红毒效果.>}
    for _, splitStr in pairs(strList) do
        retStr = ""
        if string.sub(splitStr, 1, 1) == "|" then
            retStr = retStr .. "\n"
        end

        -- like Text|x=25|y=20|color=250|size=18|text=施毒术使用必需品.
        splitStr_2 = string.gsub(splitStr, "[%<]", "")

        -- like {Text,x=25,y=20, color=250, size=18, text=施毒术使用必需品.}
        splitStr_3 = string.split(splitStr_2, "|")

        -- 先找到文本
        for _, splitStr_4 in pairs(splitStr_3) do
            if string.contains(splitStr_4, "text") then
                -- resStr=施毒术使用必需品.
                retStr = retStr .. string.replace(splitStr_4, "text=", "")
            end
        end

        -- 在找其他
        for _, splitStr_4 in pairs(splitStr_3) do
            if string.contains(splitStr_4, "color") then

                local rgbId = tonumber(string.replace(splitStr_4, "color=", ""))
                local a = ConfigManager.Get_cfg_color(tonumber(rgbId))
                local rgbConfig = ConfigManager.Get_cfg_color(tonumber(rgbId)).color
                -- like <color=#00ff00>施毒术使用必需品</color>
                retStr = string.format("<color=%s>", rgbConfig) .. retStr
                retStr = retStr .. "</color>"
            end
        end

        table.insert(retStrList, retStr)
    end

    return table.concat(retStrList, "")
end

