this.leftTop = 0
this.leftButtom = 0
this.rightTop = 0
this.rightButtom = 0
this.top = 11
this.buttom = 9
---@param coord Dot2
function this.IsRoleInView(coord)
    if not RoleManager.meData then
        return
    end
    if Dot2.DistancePow2(RoleManager.meData.OldCoord, coord) > 169 then
        return false
    end

    this.leftTop = (this.top) * (coord.z - (RoleManager.meData.OldCoord.z))
            - (-this.buttom) * (coord.x - (RoleManager.meData.OldCoord.x - this.top))

    this.leftButtom = (this.top) * (coord.z - (RoleManager.meData.OldCoord.z - this.buttom))
            - (this.buttom) * (coord.x - RoleManager.meData.OldCoord.x)

    this.rightTop = (-this.top) * (coord.z - RoleManager.meData.OldCoord.z)
            - (this.top) * (coord.x - (RoleManager.meData.OldCoord.x + this.top))

    this.rightButtom = (-this.top) * (coord.z - (RoleManager.meData.OldCoord.z + this.top))
            - (-this.buttom) * (coord.x - (RoleManager.meData.OldCoord.x))

    if ((this.leftTop > 0 and this.leftButtom > 0 and this.rightTop > 0 and this.rightButtom > 0) or (this.leftTop < 0 and this.leftButtom < 0 and this.rightTop < 0 and this.rightButtom < 0)) then
        return true
    end
    return false
end

function this:IsRoleEnterMapPointRange(x, z, range)
