function this.GetBloodColorByStage(stage, specialBloodtab)
    local index = stage % (#specialBloodtab - 1)
    if index == 0 then
        index = #specialBloodtab
    else
        index = index + 1
    end
    local hpColorId = specialBloodtab[index]
    local hpBgColorId
    if index == #specialBloodtab then
        hpBgColorId = specialBloodtab[2]
    else
        hpBgColorId = specialBloodtab[index + 1]
    end
    if ConfigManager.Exsit_cfg_color(hpColorId) and ConfigManager.Exsit_cfg_color(hpBgColorId) then
        return string.replace(ConfigManager.Get_cfg_color(hpColorId).color, '#', '0x'), string.replace(ConfigManager.Get_cfg_color(hpBgColorId).color, '#', '0x')
        -- return ColorUtil.TryParseHtmlStringToColor(ConfigManager.Get_cfg_color(hpColorId).color) ,ColorUtil.TryParseHtmlStringToColor(ConfigManager.Get_cfg_color(hpBgColorId).color)
    end
    return nil, nil
end

