function this.NumberToChinese(num)
    local chineseNum = { "零", "一", "二", "三", "四", "五", "六", "七", "八", "九" }
    local chineseUnit = { "", "十", "百", "千", "万", "亿" }
    if num == 0 then
        return chineseNum[1]
    end
    local result = ""
    local unitPos = 1
    local nonZero = false

    while num > 0 do
        local digit = num % 10
        if digit > 0 then
            if unitPos == 2 then
                result = chineseUnit[unitPos] .. result
            else
                result = chineseNum[digit + 1] .. chineseUnit[unitPos] .. result
            end

            nonZero = true
        elseif (unitPos == 5 and result:sub(1, 1) ~= chineseNum[1]) or (unitPos ~= 5 and nonZero) then
            result = chineseNum[digit + 1] .. result
            nonZero = false
        end
        num = math.floor(num / 10)
        unitPos = unitPos + 1
    end
    return result
end

local lastCollectFuncCallCountsTime = 0
local collectFuncCallCounts = {}
---@return boolean @ 用来查找死循环调用的 使用 在函数开头 if not Misc.IsCanFuncCallByLimitCount() then return end
function this.IsCanFuncCallByLimitCount(tableName, funcName, limitCallTime)
    if Time.frameCount ~= lastCollectFuncCallCountsTime then
        table.clear(collectFuncCallCounts)
    end
    if not collectFuncCallCounts[tableName] then
        collectFuncCallCounts[tableName] = {}
    end
    if limitCallTime == nil then
        limitCallTime = 100
    end
    collectFuncCallCounts[tableName][funcName] = collectFuncCallCounts[tableName][funcName] and collectFuncCallCounts[tableName][funcName] + 1 or 1
    if collectFuncCallCounts[tableName][funcName] > limitCallTime then
        logError(tableName, funcName, ' call too much > ', limitCallTime)
        return false
    end
    return true
end

function this.GetSampleNumberString(numArg)
    local num = tonumber(numArg)
    if not num then return numArg end
    if num < 10000 then
        --5位
        return num
    elseif num < 100000000 then
        --9位
        return math.floor(num / 1000 + 0.5) / 10 .. "万"
    elseif num < 1000000000000 then
        --13位
        return math.floor(num / 10000000 + 0.5) / 10 .. "亿"
    elseif num < 10000000000000000 then
        --17位
        return math.floor(num / 100000000000 + 0.5) / 10 .. "兆"
    else
        return math.floor(num / 100000000000 + 0.5) / 10 .. "兆"
    end

    return ""
end

function this.GetSampleNumberString2(num)
    if num < 10000 then
